"""Generates src/fieldmap9.ts from MPXJ's FieldMap9.java.

Project 2000-2003 files (MPP9) often carry no field map of their own, and
MPXJ then falls back to the field layout FieldMap9 spells out. This copies
that layout - field, where it is stored, block, offset and variable-data key -
for the task, resource and assignment fields the reader knows.

    python tools/gen_fieldmap9.py <path to an MPXJ checkout>
"""

import re
import sys
from pathlib import Path

mpxj = Path(sys.argv[1])
src = (mpxj / 'src/main/java/org/mpxj/mpp/FieldMap9.java').read_text(encoding='utf-8')
item = re.compile(r'new FieldItem\((Task|Resource|Assignment)Field\.(\w+),\s*FieldLocation\.(\w+),\s*(\d+),\s*(\d+),\s*(\d+),\s*(\d+),\s*(\d+)\)')
where = {'FIXED_DATA': 'fixed', 'VAR_DATA': 'var', 'META_DATA': 'meta', 'UNKNOWN': 'unknown'}
groups = {'Task': [], 'Resource': [], 'Assignment': []}
for m in item.finditer(src):
    cls, name, loc, block, offset, var_key, _mask, _meta_block = m.groups()
    groups[cls].append(f'  ["{name}", "{where[loc]}", {block}, {offset}, {var_key}],')

out = ['// Generated by tools/gen_fieldmap9.py from MPXJ\'s FieldMap9 (LGPL-2.1); do not edit by hand.',
       '// The field layout Project 2000-2003 files use when they carry no field map:',
       '// [field name, location, fixed-data block, offset, variable-data key].',
       '',
       "export type DefaultItem = readonly [name: string, location: 'fixed' | 'var' | 'meta' | 'unknown', block: number, offset: number, varKey: number];",
       '']
for cls in ('Task', 'Resource', 'Assignment'):
    out.append(f'export const {cls.upper()}_DEFAULTS_9: readonly DefaultItem[] = [')
    out.extend(groups[cls])
    out.append('];')
    out.append('')
Path(__file__).resolve().parent.parent.joinpath('src/fieldmap9.ts').write_text('\n'.join(out), encoding='utf-8')
print({k: len(v) for k, v in groups.items()})
